#include "ui/renderer.h"
#include <iostream>
int main(){OleInitialize(nullptr);int result=0;try{WNDCLASSW c{};c.hInstance=GetModuleHandleW(nullptr);c.lpszClassName=L"Delight.GraphicsTest";c.lpfnWndProc=DefWindowProcW;RegisterClassW(&c);HWND w=CreateWindowExW(WS_EX_NOREDIRECTIONBITMAP,c.lpszClassName,L"Graphics test",WS_POPUP,0,0,448,72,nullptr,nullptr,c.hInstance,nullptr);{delight::Renderer r;r.initialize(w);for(int i=0;i<32;++i)r.draw(224,36,192,{{L"Glide Island",18,8,14,false}},false,false,{{delight::Glyph::Timer,190,6,24,true,false,24,i/32.f}});}DestroyWindow(w);std::cout<<"Composition initialization and DirectWrite surface drawing passed\n";}catch(const winrt::hresult_error& e){std::wcerr<<L"Graphics error 0x"<<std::hex<<static_cast<unsigned>(e.code())<<L": "<<e.message().c_str()<<L'\n';result=1;}OleUninitialize();return result;}
